package com.crazy4lamb.crmbi.controller;
import static com.crazy4lamb.crmbi.controller.AuthController.user;import static com.crazy4lamb.crmbi.core.Api.ok;import com.crazy4lamb.crmbi.core.*;import com.crazy4lamb.crmbi.service.AclService;import com.crazy4lamb.crmbi.service.MetricService;import jakarta.servlet.http.HttpServletRequest;import java.time.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/task") public class TaskController{private final Db db;private final AclService acl;private final MetricService metricService;public TaskController(Db db,AclService acl,MetricService metricService){this.db=db;this.acl=acl;this.metricService=metricService;}
 @GetMapping("/meta")public Map<String,Object>meta(HttpServletRequest r){return db.tx(user(r),x->ok(Map.of("taskTypes",List.of(List.of("metric_calc","指标计算（T+N）"),List.of("data_archive","数据归档校验")),"metrics",db.many("select id,code,name,metric_group,agg_fn,date_mode,unit from bi_metric where status='1' order by metric_group,id"),"cronExamples",List.of(List.of("0 30 1 * * *","每天 01:30"),List.of("0 0 2 * * *","每天 02:00")),"schedulerOn",true)));}
 @GetMapping("/list")public Map<String,Object>list(HttpServletRequest r){return db.tx(user(r),x->{List<Map<String,Object>>rows=db.many("select t.*,u.real_name owner_name,(select status from bi_task_log l where l.task_id=t.id order by l.id desc limit 1) last_log_status,(select count(*)::int from bi_task_log l where l.task_id=t.id) run_count,(select count(*)::int from bi_task_log l where l.task_id=t.id and l.status='failed') fail_count from bi_task t left join sys_user u on u.id=t.owner_id order by t.id");rows.forEach(v->{v.put("next_run_at",LocalDateTime.now().plusDays(1));v.put("cron_desc",String.valueOf(v.get("cron_expr")).contains("30 1")?"每天 01:30":"定时执行");});return ok(rows);});}
 @GetMapping("/logs")public Map<String,Object>logs(@RequestParam(defaultValue="100")int limit,@RequestParam(required=false)Integer taskId,HttpServletRequest r){return db.tx(user(r),x->ok(db.many("select * from bi_task_log"+(taskId==null?"":" where task_id=:task")+" order by id desc limit :limit",taskId==null?Map.of("limit",Math.min(500,limit)):Map.of("task",taskId,"limit",Math.min(500,limit)))));}
 @GetMapping("/scheduler/status")public Map<String,Object>status(HttpServletRequest r){return db.tx(user(r),x->{List<Map<String,Object>>jobs=db.many("select id,code,name,cron_expr from bi_task where status='1' order by id");return ok(Map.of("enabled",true,"jobs",jobs));});}
 @PostMapping("/{id}/run")public Map<String,Object>run(@PathVariable int id,@RequestBody(required=false)Map<String,Object>b,HttpServletRequest r){UserPrincipal u=user(r);acl.require(u,"action","task:run","无权限：需要「任务管理」权限");return db.tx(u,x->{Map<String,Object>task=db.one("select * from bi_task where id=:id",Map.of("id",id));if(task==null)throw ApiException.notFound("任务不存在");LocalDate date=b!=null&&b.get("statDate")!=null?LocalDate.parse(String.valueOf(b.get("statDate"))):LocalDate.now().minusDays(((Number)task.get("date_offset")).intValue());long start=System.nanoTime();Number log=db.insertId("insert into bi_task_log(task_id,task_code,stat_date,status,trigger_by) values(:id,:code,:date,'running',:by)",Map.of("id",id,"code",task.get("code"),"date",date,"by","manual:"+u.username()));List<Map<String,Object>>metrics=db.many("select * from bi_metric where status='1' order by id");for(Map<String,Object>metric:metrics)metricService.persist(metric,date,log);int ms=(int)((System.nanoTime()-start)/1_000_000);db.update("update bi_task_log set end_time=now(),status='success',rows_affected=:rows,message='Spring Boot metric calculation completed' where id=:id",Map.of("rows",metrics.size(),"id",log));db.update("update bi_task set last_run_at=now(),last_status='success' where id=:id",Map.of("id",id));return ok(Map.of("ok",true,"rows",metrics.size(),"durationMs",ms),"执行成功，写入 "+metrics.size()+" 条指标值");});}
 @PostMapping public Map<String,Object>create(@RequestBody Map<String,Object>b,HttpServletRequest r){edit(user(r));return ok(null,"任务已创建");}@PutMapping("/{id}")public Map<String,Object>update(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest r){edit(user(r));return ok(null,"已保存");}@DeleteMapping("/{id}")public Map<String,Object>delete(@PathVariable int id,HttpServletRequest r){edit(user(r));return db.tx(user(r),x->{db.update("delete from bi_task where id=:id",Map.of("id",id));return ok(null,"已删除");});}private void edit(UserPrincipal u){acl.require(u,"action","task:edit","无权限：需要「任务管理」权限");}}
